  "settings.history.title": "Historial y restauración",
  "settings.history.intro":
    "Todo lo que agrega, cambia o elimina queda registrado aquí. Si algo sale mal (una herramienta eliminada por accidente, una lista entera borrada), elija un punto de restauración y su cuenta vuelve exactamente a como estaba entonces. Los registros compartidos con otras personas (préstamos, listas de herramientas compartidas, reclamos presentados) se muestran para que el historial esté completo, pero nunca se revierten: restaurar su cuenta no reescribe la de nadie más. Los archivos eliminados se conservan un tiempo para que las restauraciones también devuelvan sus fotos.",
