  "walk.claim.s1.title": "Elige la herramienta averiada",
  "walk.claim.s1.intro": "El reclamo es para esta herramienta: su distribuidor y su valor salen de su propio registro.",
  "walk.claim.s1.empty": "Aún no tienes herramientas ni baterías: agrega una en Inventario primero y luego vuelve para presentar su reclamo desde aquí.",
  "walk.claim.s2.title": "¿Qué pasó?",
  "walk.claim.s2.intro": "Cuéntalo con tus palabras, con una frase basta. Queda en el reclamo tal como lo escribes, y luego puedes agregar fotos.",
  "walk.claim.s2.example": "«El mandril se tambalea y dejó de sujetar las brocas». Corto y claro está perfecto.",
  "walk.claim.s3.title": "¿Ante quién se presenta el reclamo?",
  "walk.claim.s3.intro": "La mayoría de los reclamos de reparación van por tu agente del distribuidor. Elige otra ruta si el tuyo funciona distinto.",
  "walk.claim.s3.noDealer": "Esta herramienta no nombra un distribuidor, así que no hay nadie ante quién presentarlo: el reclamo lo llevas tú, y aun así se presenta de verdad en el siguiente paso.",
