  "seo.description.home": "Toolbox Vault — el inventario de herramientas creado por un mecánico, para mecánicos. Documenta cada herramienta con fotos, números de serie y valores; prepárate para reclamos de seguro, reparaciones y recuperación. Gratis para empezar.",
  "seo.description.downloads": "Documentos y hojas de trabajo gratuitos para el taller, un convertidor de unidades integrado y archivos de impresión 3D gratuitos compartidos por miembros — sin cuenta, sin correo, solo descarga.",
  "seo.description.prints": "Descarga archivos de impresión 3D gratuitos para almacenar herramientas y organizar tu taller — rieles para dados, soportes, monturas y más, compartidos por mecánicos. Sin cuenta, sin correo, solo descarga.",
