  "seo.description.signup": "Crea tu cuenta gratuita de Toolbox Vault y comienza a documentar tus herramientas hoy — fotos, números de serie, valores y registros listos para el seguro. Tus primeras 20 herramientas son gratis.",
  "seo.description.default": "Toolbox Vault — el inventario de herramientas creado por un mecánico, para mecánicos. Documenta cada herramienta con fotos, números de serie y valores; prepárate para reclamos de seguro, reparaciones y recuperación. Gratis para empezar.",
